// Encapsulation
public class BankAccount {
    private decimal balance; // Hidden data
    public void Deposit(decimal amount) { // Controlled access
        if (amount > 0) balance += amount;
    }
}

// Abstraction
public interface IPaymentProcessor {
    void ProcessPayment(decimal amount);
}

// Inheritance
public class PremiumAccount : BankAccount {
    public void ApplyCashback() { }
}

// Polymorphism
IPaymentProcessor processor = new CreditCardProcessor();
processor.ProcessPayment(100); // Same interface, different behavior
